// drop(e, f): min worst-case drops with e eggs and f floors
private int drop(int e, int f) {
    if (f == 0 || f == 1) {
        return f;
    }
    if (e == 1) {
        return f;
    }
    int best = Integer.MAX_VALUE;
    for (int x = 1; x <= f; x++) {
        int broke = drop(e - 1, x - 1);
        int survived = drop(e, f - x);
        int worst = 1 + Math.max(broke, survived);
        best = Math.min(best, worst);
    }
    return best;
}

