def egg_drop(self, k: int, n: int) -> int:
    def drop(e: int, f: int) -> int:
        if f == 0 or f == 1:
            return f
        if e == 1:
            return f
        best = float('inf')
        for x in range(1, f + 1):
            broke = drop(e - 1, x - 1)
            survived = drop(e, f - x)
            best = min(best, 1 + max(broke, survived))
        return best

    return drop(k, n)

