public int eggDrop(int k, int n) {
    int[][] dp = new int[k + 1][n + 1];
    for (int e = 1; e <= k; e++) {
        dp[e][0] = 0;
        dp[e][1] = 1;
    }
    for (int f = 1; f <= n; f++) {
        dp[1][f] = f;
    }
    for (int e = 2; e <= k; e++) {
        for (int f = 2; f <= n; f++) {
            int best = Integer.MAX_VALUE;
            for (int x = 1; x <= f; x++) {
                int worst = 1 + Math.max(dp[e - 1][x - 1], dp[e][f - x]);
                best = Math.min(best, worst);
            }
            dp[e][f] = best;
        }
    }
    return dp[k][n];
}

