def egg_drop(self, k: int, n: int) -> int:
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    for e in range(1, k + 1):
        dp[e][1] = 1
    for f in range(1, n + 1):
        dp[1][f] = f
    for e in range(2, k + 1):
        for f in range(2, n + 1):
            best = float('inf')
            for x in range(1, f + 1):
                worst = 1 + max(dp[e - 1][x - 1], dp[e][f - x])
                best = min(best, worst)
            dp[e][f] = best
    return dp[k][n]

