public int eggDrop(int k, int n) {
    int[] dp = new int[k + 1];  // dp[e] = floors coverable with e eggs at the current trial count
    int trials = 0;
    while (dp[k] < n) {
        trials++;
        // iterate eggs DESCENDING so dp[e - 1] still holds the previous-trial value
        for (int e = k; e >= 1; e--) {
            dp[e] = dp[e] + dp[e - 1] + 1;
        }
    }
    return trials;
}

